import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(t):
        try:
            n = int(next(iterator))
        except StopIteration:
            break

        # Consume the n-1 edges
        for _ in range(n - 1):
            next(iterator)
            next(iterator)

        if n == 1:
            results.append("0")
        elif n == 2:
            results.append("1")
        else:
            results.append("2")

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == "__main__":
    solve()
